1	/**
2	 * Очередь исходящих.
3	 *
4	 * Уведомления накапливаются и уходят разом по `drain`. Очередь — объект, а не состояние
5	 * модуля: у каждого вызывающего своя, и тесты не делят одну очередь через общий импорт.
6	 * Порядок отдачи — порядок постановки: `drain` отправляет то, что накопилось, и ничего
7	 * не переставляет.
8	 */
9	
10	import { logEvent } from './log.ts';
11	import type { OutMessage } from './message.ts';
12	import { sendNotification } from './sender.ts';
13	import type { Transport } from './transport.ts';
14	
15	export interface Outbox {
16	  /** Поставить уведомление в очередь. Ничего не отправляет. */
17	  enqueue(msg: OutMessage): void;
18	  /** Отправить всё накопленное через транспорт. Возвращает id отправок в порядке отправки; очередь пустеет. */
19	  drain(transport: Transport): string[];
20	  /** Сколько уведомлений ждёт отправки. */
21	  pending(): number;
22	}
23	
24	export function createOutbox(): Outbox {
25	  const queue: OutMessage[] = [];
26	  return {
27	    enqueue(msg: OutMessage): void {
28	      queue.push(msg);
29	    },
30	    drain(transport: Transport): string[] {
31	      const ids: string[] = [];
32	      for (const msg of queue) ids.push(sendNotification(transport, msg).id);
33	      queue.length = 0;
34	      // В журнал идёт счётчик, не адресаты: см. README, «персональные данные не пишутся».
35	      logEvent(`отправлено из очереди: ${ids.length}`);
36	      return ids;
37	    },
38	    pending(): number {
39	      return queue.length;
40	    },
41	  };
42	}
43

